<?php
if ( ! defined( 'ABSPATH' ) || ! is_user_logged_in() ) { return; }
global $wpdb;
$email = wp_get_current_user()->user_email;
$summary = $wpdb->get_row( $wpdb->prepare( "SELECT COALESCE(SUM(p.quantity),0) AS entries, COUNT(DISTINCT p.raffle_id) AS competitions FROM {$wpdb->prefix}raffle_purchases p WHERE p.buyer_email = %s AND p.payment_status = 'completed'", $email ) );
$upcoming = $wpdb->get_results( $wpdb->prepare( "SELECT r.id, r.title, r.draw_date, r.wc_product_id, SUM(p.quantity) AS entries FROM {$wpdb->prefix}raffle_purchases p JOIN {$wpdb->prefix}raffles r ON r.id = p.raffle_id WHERE p.buyer_email = %s AND p.payment_status = 'completed' AND r.winner_ticket_id IS NULL AND r.status IN ('active','finished') GROUP BY r.id, r.title, r.draw_date, r.wc_product_id ORDER BY r.draw_date IS NULL, r.draw_date ASC LIMIT 20", $email ) );
$wins = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->prefix}raffle_tickets t WHERE t.buyer_email = %s AND (EXISTS (SELECT 1 FROM {$wpdb->prefix}raffles r WHERE r.winner_ticket_id = t.id) OR EXISTS (SELECT 1 FROM {$wpdb->prefix}raffle_prizes p WHERE p.winner_ticket_id = t.id))", $email ) );
?>
<section class="wpraffle-overview"><h3><?php esc_html_e( 'My competition overview', 'wpraffle' ); ?></h3>
<?php if ( $upcoming ) : $next = $upcoming[0]; ?>
<article class="wpraffle-next-draw"><p class="wpraffle-overview-label"><?php esc_html_e( 'Your next draw', 'wpraffle' ); ?></p><h4><?php echo esc_html( $next->title ); ?></h4><p><?php echo esc_html( $next->draw_date ? mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $next->draw_date ) : __( 'Date to be announced', 'wpraffle' ) ); ?></p><p><?php echo esc_html( sprintf( __( '%d confirmed entries · awaiting a winner', 'wpraffle' ), $next->entries ) ); ?></p><a class="button" href="<?php echo esc_url( add_query_arg( 'sub', 'tickets', wc_get_account_endpoint_url( 'my-raffles' ) ) ); ?>"><?php esc_html_e( 'View my tickets', 'wpraffle' ); ?></a></article>
<?php else : ?><div class="wpraffle-overview-empty"><p><?php esc_html_e( 'You have no draws awaiting a winner.', 'wpraffle' ); ?></p><a class="button" href="<?php echo esc_url( wc_get_page_permalink( 'shop' ) ); ?>"><?php esc_html_e( 'Browse competitions', 'wpraffle' ); ?></a></div><?php endif; ?>
<h4><?php esc_html_e( 'Your entry history', 'wpraffle' ); ?></h4>
<dl class="wpraffle-overview-stats"><div><dt><?php esc_html_e( 'Confirmed entries', 'wpraffle' ); ?></dt><dd><?php echo esc_html( (int) $summary->entries ); ?></dd></div><div><dt><?php esc_html_e( 'Competitions entered', 'wpraffle' ); ?></dt><dd><?php echo esc_html( (int) $summary->competitions ); ?></dd></div><div><dt><?php esc_html_e( 'Winning tickets', 'wpraffle' ); ?></dt><dd><?php echo esc_html( $wins ); ?></dd></div></dl>
<?php if ( function_exists( 'woo_wallet' ) && is_object( woo_wallet() ) && isset( woo_wallet()->wallet ) ) : ?><p><?php esc_html_e( 'Wallet balance:', 'wpraffle' ); ?> <?php echo wp_kses_post( woo_wallet()->wallet->get_wallet_balance( get_current_user_id() ) ); ?></p><?php endif; ?>
<h4><?php esc_html_e( 'Upcoming draws for my entries', 'wpraffle' ); ?></h4>
<?php if ( ! $upcoming ) : ?><p><?php esc_html_e( 'You have no draws awaiting a winner.', 'wpraffle' ); ?></p><?php else : ?><ul><?php foreach ( $upcoming as $r ) : ?><li><a href="<?php echo esc_url( $r->wc_product_id ? get_permalink( $r->wc_product_id ) : wc_get_account_endpoint_url( 'my-raffles' ) ); ?>"><?php echo esc_html( $r->title ); ?></a> — <?php echo esc_html( sprintf( __( '%d entries', 'wpraffle' ), $r->entries ) ); ?> — <?php echo esc_html( $r->draw_date ? mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $r->draw_date ) : __( 'Draw date to be announced', 'wpraffle' ) ); ?></li><?php endforeach; ?></ul><?php endif; ?>
</section>
